"use client";

import { motion, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import type { ComponentProps, ReactNode } from "react";

export type HoldToConfirmPrimitiveProps = Omit<ComponentProps<typeof motion.button>, "children" | "onPointerDown" | "onPointerUp" | "onPointerCancel" | "onPointerLeave" | "onKeyDown" | "onKeyUp"> & {
  children: ReactNode;
  holdMs?: number;
  onConfirm: () => void;
};

export function HoldToConfirmPrimitive({ children, holdMs = 1200, onConfirm, ...props }: HoldToConfirmPrimitiveProps) {
  const reduceMotion = useReducedMotion();
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [holding, setHolding] = useState(false);

  function cancelHold() {
    if (timer.current) clearTimeout(timer.current);
    timer.current = null;
    setHolding(false);
  }

  function startHold() {
    if (props.disabled || timer.current) return;
    setHolding(true);
    timer.current = setTimeout(() => {
      timer.current = null;
      setHolding(false);
      onConfirm();
    }, holdMs);
  }

  useEffect(() => cancelHold, []);

  return (
    <motion.button
      {...props}
      type={props.type ?? "button"}
      aria-pressed={holding}
      style={{ ...props.style, position: props.style?.position ?? "relative", overflow: "hidden" }}
      onPointerDown={startHold}
      onPointerUp={cancelHold}
      onPointerCancel={cancelHold}
      onPointerLeave={cancelHold}
      onKeyDown={(event) => {
        if ((event.key === " " || event.key === "Enter") && !event.repeat) {
          event.preventDefault();
          startHold();
        }
      }}
      onKeyUp={(event) => {
        if (event.key === " " || event.key === "Enter") cancelHold();
      }}
      whileTap={reduceMotion ? undefined : { scale: 0.98 }}
    >
      <motion.span
        aria-hidden="true"
        initial={false}
        animate={{ scaleX: holding ? 1 : 0, opacity: holding ? 0.12 : 0 }}
        transition={reduceMotion ? { duration: 0.12 } : { duration: holding ? holdMs / 1000 : 0.14, ease: "linear" }}
        style={{ position: "absolute", inset: 0, background: "currentColor", transformOrigin: "left", pointerEvents: "none" }}
      />
      <span style={{ position: "relative" }}>{children}</span>
    </motion.button>
  );
}
